"""Generated from the game's data tables. Do not edit by hand."""

from typing import NamedTuple


class Spawn(NamedTuple):
    cell: int                   # u16 address of the borg id
    borg: int | None            # None = random in vanilla (bit 0x8000): pinned per seed
    level: int
    choices: tuple[int, ...]    # the ids a random spawn draws from


class StatTarget(NamedTuple):
    ai_cell: int
    level_cell: int
    ai: int                     # vanilla; scenario AI keeps its high nibble at 0 (voice selector)
    level: int                  # vanilla


class CommanderTarget(NamedTuple):
    participant: int
    ai_cell: int
    vanilla_ai: int             # the whole byte: (vanilla_ai & 0xF0) | ai keeps the high nibble
    level_cell: int
    level: int                  # vanilla
    latest_chapter: int         # the deepest chapter that uses the participant: its sphere rules


